--
-- Table structure for table `produtos_fornecedores_catalogo`
--

DROP TABLE IF EXISTS `produtos_fornecedores_catalogo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `produtos_fornecedores_catalogo` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `ProdutoPaiId` int NOT NULL,
  `FornecedorId` int NOT NULL,
  `PrecoCustoTabela` decimal(10,2) NOT NULL,
  `CodigoProdutoNoFornecedor` varchar(50) DEFAULT NULL,
  `IsFornecedorPrincipal` tinyint(1) DEFAULT '0',
  `DataUltimaAtualizacao` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`Id`),
